out=[]
for p in P:
    x=dict(zip(F,p)); x["slug"]=re.sub(r"[^a-z0-9]+","-",(x["authors"].split(",")[0].split(" ")[0]+" "+str(x["year"])+" "+x["topic"]).lower()).strip("-")
    x["url"]="https://doi.org/"+x["doi"] if x["doi"] else None; x["emoji"]="📄"; x["group"]=x["topic"]
    out.append(x)
# de-duplicate slugs
seen={}
for x in out:
    if x["slug"] in seen: seen[x["slug"]]+=1; x["slug"]+=f"-{seen[x['slug']]}"
    else: seen[x["slug"]]=1
json.dump(out,open('../papers.json','w'),ensure_ascii=False,indent=0); print(len(out))
